    );
}

function makeConfig(overrides) {
    var base = { git: { baseBranch: 'master' }, workingDir: 'dependencies/proj' };
    return Object.assign({}, base, overrides || {});
}

function makeConfigLoaderStub(hookFn, hookLoadCalls) {
