            'Error logs: {code}ci_failures.md{code} (summary) and {code}ci_failures_full.log{code} (full logs).') !== -1,
            'CI panel lists every failing check');
        assert.ok(out.indexOf('_Fix results will be posted shortly..._') !== -1);
