            __ghStub: ghStub,
            cli_execute_command: function(opts) { cliCalls.push(opts.command); return ''; }
        });

        mod.syncBaseBranchIfConfigured('master', { branchSyncFnPath: '.dmtools/branchNaming/sf_rc_jenkins.js' }, makeConfig());

