        assert.ok(out.indexOf('### 🔧 Automated Rework Started\n') === 0, 'starts with a markdown heading');
        assert.ok(out.indexOf('**Pull Request**: [PR #1308](https://github.com/acme/widgets/pull/1308)\n') !== -1);
        assert.ok(out.indexOf('**Branch**') !== -1);
