/**
 * Main action function.
 *
 * Fetches PR data for rework and prepares context for the CLI agent.
 *
 * @param {Object} params - The parameters object
 * @returns {Object} The result object
 */
function action(params) {
   try {
       const parsed = parseReworkParams(params);
       const inputFolder = parsed.inputFolder;
       const ticketKey = parsed.ticketKey;
       const prAnchor = parsed.prAnchor;
       const config = configLoader.loadProjectConfig(configLoader.paramsForConfigLoad(params));
       const customParams = (params.jobParams && params.jobParams.customParams) || parsed.actualParams.customParams;
       const scm = configLoader.createScm(config);
       const statuses = resolveStatuses(customParams, config.jira && config.jira.statuses);
       const tracker = trackersModule.createTracker(config, customParams);

       try {
           restoreFromReleases.action(params);
       } catch (e) {
           console.warn('⚠️ restoreFromReleases failed (non-fatal):', e);
       }

       console.log('=== Rework setup for:', ticketKey, '==');

       moveTicketToReworkStatus(config, tracker, ticketKey, statuses, prAnchor);

       // Step 2: Get repo info
       const repoInfo = resolveRepoInfo(config, scm);
       if (!repoInfo) {
           var err = 'Could not resolve repository info from git remote (override via targetRepository in config).';
           var m = commentMarkup.forTicket(ticketKey, customParams);
           tracker.postComment(ticketKey, m.h(3, '❌ Rework Setup Error') + '\n' + m.code(err));
           return { success: false, error: err };
       }

       // Step 3: Find the PR to work on
       const pr = findPrForRework(prAnchor, scm, config, ticketKey);
       if (!pr) failSetup(tracker, ticketKey, inputFolder, 'No PR found for ticket ' + ticketKey, customParams);

       const prDetails = gh.getPRDetails(scm, pr.number);
       if (!prDetails) failSetup(tracker, ticketKey, inputFolder, 'Could not get PR details for #' + pr.number, customParams);

       const branchName = prDetails.head ? prDetails.head.ref : null;
       if (!branchName) failSetup(tracker, ticketKey, inputFolder, 'Could not determine branch name from PR #' + prDetails.number, customParams);

       checkoutReworkBranch(branchName, config, inputFolder, tracker, ticketKey, customParams);

       // Checkout the base branch to get it locally (needed for conflict detection)
       const baseBranch = prDetails.base ? prDetails.base.ref : config.git.baseBranch;
       baseBranchMarker.writeBaseBranchMarker(baseBranch);
       syncBaseBranchIfConfigured(baseBranch, customParams, config);

       const conflictFiles = gitOps.detectMergeConflicts(baseBranch, inputFolder, config.workingDir);

       runSetupCommandsStep(customParams, config, inputFolder, tracker, ticketKey);

       // Fetch PR head SHA for the stale-head guard (post-cli verifies HEAD did not move)
       const headSha = prDetails.head ? prDetails.head.sha : null;
       const failedChecks = gh.detectFailedChecks(scm, prDetails.number, headSha);

       // Fetch PR diff and discussions
       const diff = gitOps.getPRDiff(scm, prDetails.number, config.workingDir);
       console.log('Fetching PR discussions...');
       const discussionData = gh.fetchDiscussionsAndRawData(scm, prDetails.number);

       // Write everything to input folder
       gitOps.writePRContext(inputFolder, prDetails, diff, discussionData.markdown, discussionData.rawThreads);

       // Persist PR head SHA for the no-fix-on-stale-head guard
       writeReworkBaseHead(inputFolder, headSha);

       try {
           ensureInputContextContract(inputFolder, scm, prDetails.number, discussionData, failedChecks);
       } catch (e) {
           console.warn('Input contract enforcement failed (non-fatal):', e);
       }

       try {
           fetchQuestionsToInput.action(parsed.actualParams);
       } catch (e) {
           console.warn('Failed to fetch questions (non-fatal):', e);
       }

       if (prAnchor) {
           console.log('PR-anchored rework: skipping tracker comment (no ticket, #544)');
       } else {
           postReworkStartedCommentStep(tracker, ticketKey, customParams, {
               prNumber: prDetails.number,
               prUrl: prDetails.html_url,
               branchName: branchName,
               conflictFiles: conflictFiles,
               failedChecks: failedChecks,
           });
       }

       console.log('✅ Rework setup complete — branch:', branchName, '| PR #' + prDetails.number);

       try {
           fetchParentContextToInput.action(params);
       } catch (e) {
           console.warn('fetchParentContextToInput failed (non-fatal):', e);
       }

       return { success: true, prNumber: prDetails.number, prUrl: prDetails.html_url, branchName: branchName, owner: repoInfo.owner, repo: repoInfo.repo };
   } catch (error) {
       console.error('❌ Error in preCliReworkSetup:', error);
       reportActionError(params, tracker, error);
       return { success: false, error: error.toString() };
   }
```

