function loadPreCliReworkSetup(configLoaderStub, mocks) {
    return loadModule(
        'js/preCliReworkSetup.js',
        makeRequire({
            './configLoader.js': configLoaderStub,
            './common/githubHelpers.js': mocks.__ghStub,
            './common/gitOps.js': NOOP_MODULE,
