// regressions = score grew; newOverThreshold = unseen function with score > 8.
import { readFileSync } from 'fs';

function parse(p) {
  const map = new Map();
  for (const line of readFileSync(p, 'utf8').split('\n')) {
    const m = /^(\S+)\s+(\S+)\s+(\d+)\s+([\d.]+)%\s+([\d.]+)$/.exec(line.trim());
    if (!m) continue;
    const [, name, file, , , crap] = m;
    const key = `${file}::${name}`;
    if (!map.has(key)) map.set(key, parseFloat(crap)); // first occurrence; duplicates are tiny test fns
  }
  return map;
}

