const after = parse(process.argv[3]);
const threshold = 8, EPS = 1e-9;
const regressions = [], newOver = [], improvements = [];
for (const [key, score] of after) {
  const b = before.get(key);
  if (b === undefined) {
    if (score > threshold) newOver.push([key, score]);
  } else if (score > b + EPS) {
    regressions.push([key, b, score]);
  } else if (score < b - EPS) {
    improvements.push([key, b, score]);
  }
}
const removed = [...before.keys()].filter(k => !after.has(k));
console.log(`regressions: ${regressions.length}`);
