// Compare two crap4js threshold-99999 reports with compareBaseline semantics:
// regressions = score grew; newOverThreshold = unseen function with score > 8.
import { readFileSync } from 'fs';

function parse(p) {
  const map = new Map();
  for (const line of readFileSync(p, 'utf8').split('\n')) {
    const m = /^(\S+)\s+(\S+)\s+(\d+)\s+([\d.]+)%\s+([\d.]+)$/.exec(line.trim());
    if (!m) continue;
    const [, name, file, , , crap] = m;
    const key = `${file}::${name}`;
    if (!map.has(key)) map.set(key, parseFloat(crap)); // first occurrence; duplicates are tiny test fns
  }
  return map;
}

const before = parse(process.argv[2]);
const after = parse(process.argv[3]);
const threshold = 8, EPS = 1e-9;
const regressions = [], newOver = [], improvements = [];
for (const [key, score] of after) {
  const b = before.get(key);
  if (b === undefined) {
    if (score > threshold) newOver.push([key, score]);
  } else if (score > b + EPS) {
    regressions.push([key, b, score]);
  } else if (score < b - EPS) {
    improvements.push([key, b, score]);
  }
}
const removed = [...before.keys()].filter(k => !after.has(k));
console.log(`regressions: ${regressions.length}`);
regressions.slice(0, 20).forEach(r => console.log('  REGRESSION', r.join(' -> ')));
console.log(`new over threshold: ${newOver.length}`);
newOver.forEach(r => console.log('  NEW > 8', r.join(': ')));
console.log(`improvements: ${improvements.length}`);
improvements.forEach(r => console.log('  improved', r.join(' -> ')));
console.log(`removed: ${removed.length}`);
process.exit(regressions.length || newOver.length ? 2 : 0);
EOF
echo ready"}

