    workingDir: '/repo',
    git: { baseBranch: 'main' },
    jira: { statuses: { BACKLOG: 'Backlog' } },
    formats: { prTitle: { rework: '{ticketKey} {ticketSummary}' } }
};

var PR12 = {
    number: 12,
    html_url: 'https://github.com/acme/widgets/pull/12',
    head: { ref: 'test/PROJ-12' },
    base: { ref: 'main' }
};

