function parse(p) {
  const map = new Map();
  for (const line of readFileSync(p, 'utf8').split('\n')) {
    const m = /^(\S+)\s+(\S+)\s+(\d+)\s+([\d.]+)%\s+([\d.]+)$/.exec(line.trim());
    if (!m) continue;
    const key = `${m[2]}::${m[1]}`;
    if (!map.has(key)) map.set(key, parseFloat(m[5]));
  }
  return map;
}
const before = parse(process.argv[2]), after = parse(process.argv[3]);
const regressions = [], newOver = [], improvements = [];
for (const [key, score] of after) {
  const b = before.get(key);
  if (b === undefined) { if (score > 8) newOver.push([key, score]); }
  else if (score > b + 1e-9) regressions.push([key, b, score]);
  else if (score < b - 1e-9) improvements.push([key, b, score]);
}
console.log(`regressions: ${regressions.length}`);
regressions.slice(0,20).forEach(r => console.log('  REGRESSION', r.join(' -> ')));
console.log(`new over threshold 8: ${newOver.length}`);
newOver.forEach(r => console.log('  NEW>8', r.join(': ')));
console.log(`improvements: ${improvements.length}`);
