function captureConsole1002(fn) {
    var logs = { log: [], warn: [], error: [] };
    var orig = console;
    global.console = {
        log: function() { logs.log.push(Array.prototype.join.call(arguments, ' ')); },
        warn: function() { logs.warn.push(Array.prototype.join.call(arguments, ' ')); },
